                                  "'run_ui_shard', 'story_reveal_arrival_inverse', 'test_products', "
                                  "'ui_failure_evidence')\n"
                                  '_CLUB_E2B_CONTRACT_SHA256 = '
                                  "'5f319703db67d07817cacf26e7fbb51494fd821b1a4b91b1447250303d0a093c'\n"
                                  '_CLUB_CURRENT_ROOT = Path(__file__).resolve().parents[1]\n'
                                  '_CLUB_LOADED_HELPER_SHA256 = digest(Path(__file__).read_bytes())\n'
                                  '_club_context_cache = None\n'
                                  '_club_context_lives = []\n'
                                  '\n'
                                  '\n'
                                  'def _club_exact_current_root(root):\n'
                                  '    root = Path(root).absolute()\n'
                                  '    if root.is_symlink() or root != root.resolve() or root != '
                                  '_CLUB_CURRENT_ROOT:\n'
                                  "        raise ValueError('Unbound or symlinked club current source "
                                  "root')\n"
                                  '    return root\n'
                                  '\n'
                                  '\n'
                                  'def _club_registration():\n'
                                  '    # This import belongs to the actual current helper, outside the '
                                  'historical\n'
                                  '    # importer. Its own checked_current binds its loaded implementation '
                                  'bytes.\n'
                                  '    from Tests.ContractChecks import test_category_roam_registration as '
                                  'registration\n'
                                  '    return registration\n'
                                  '\n'
                                  '\n'
                                  'def _club_e2b_bytes(relative, raw, registration):\n'
                                  '    if relative == CONTRACT_PATH:\n'
                                  '        restored = '
                                  'registration.club_predecessor_contract(json.loads(raw))\n'
                                  '        if isinstance(restored, dict):\n'
                                  '            restored = (json.dumps(restored, indent=2, '
                                  "ensure_ascii=False) + '\\n').encode()\n"
                                  '        elif isinstance(restored, str):\n'
                                  '            restored = restored.encode()\n'
                                  '    else:\n'
                                  '        restored = registration.club_predecessor_source(relative, raw)\n'
                                  '    if not isinstance(restored, bytes) or digest(restored) != '
                                  '_CLUB_E2B_SHA256[relative]:\n'
                                  "        raise ValueError('Exact e2b reader dependency not restored: ' + "
                                  'relative)\n'
                                  '    return restored\n'
                                  '\n'
                                  '\n'
                                  'def _club_authenticate_full(root=_CLUB_CURRENT_ROOT, *, collect=False):\n'
                                  '    root = _club_exact_current_root(root)\n'
                                  '    try:\n'
                                  '        if digest((root / HELPER_PATH).read_bytes()) != '
                                  '_CLUB_LOADED_HELPER_SHA256:\n'
                                  "            raise ValueError('Loaded club historical bridge differs from "
                                  "current bytes')\n"
                                  '        registration = _club_registration()\n'
                                  '        raw_contract = (root / CONTRACT_PATH).read_bytes()\n'
                                  '        # Full actual-current admission must happen before '
                                  'projection/cache reads.\n'
                                  '        registration.checked_current(raw_contract, root)\n'
                                  '        restored = {} if collect else None\n'
                                  '        for relative in _CLUB_E2B_SHA256:\n'
                                  '            path = root / relative\n'
                                  '            if path.is_symlink() or path.resolve() != path:\n'
                                  "                raise ValueError('Symlinked finite current club input: ' "
                                  '+ relative)\n'
                                  '            raw = path.read_bytes()\n'
                                  '            old = _club_e2b_bytes(relative, raw, registration)\n'
                                  '            if collect:\n'
                                  '                restored[relative] = old\n'
                                  '        # Detect a current change made while the finite inputs were being '
                                  'read.\n'
                                  '        registration.checked_current((root / CONTRACT_PATH).read_bytes(), '
                                  'root)\n'
                                  '        return restored\n'
                                  '    except (OSError, AssertionError) as error:\n'
                                  "        raise ValueError('Current club inputs were not authenticated: ' + "
                                  'str(error)) from error\n'
                                  '\n'
                                  '\n'
                                  '\n'
                                  '# A transaction is explicit and bounded to one synchronous caller/task. '
                                  'It is\n'
                                  '# not a cross-call admission cache. Every inner reader still hashes all '
                                  'actual\n'
                                  '# current inputs; before/after complete admission brackets each outer '
                                  'scope.\n'
                                  'from contextlib import contextmanager as _club_contextmanager\n'
                                  'import asyncio as _club_asyncio\n'
                                  'import threading as _club_threading\n'
                                  '_club_active_transaction = '
                                  "_ClubContextVar('club_authenticated_reader_transaction', default=None)\n"
                                  '\n'
                                  'def _club_transaction_owner():\n'
                                  '    try: task = _club_asyncio.current_task()\n'
                                  '    except RuntimeError: task = None\n'
                                  '    return (_club_os.getpid(), _club_threading.get_ident(), task)\n'
                                  '\n'
                                  'def _club_transaction_hashes(root, paths):\n'
                                  '    values = {}\n'
                                  '    for relative in paths:\n'
                                  '        path = root / relative\n'
                                  '        if path.is_symlink() or path.resolve() != path:\n'
                                  "            raise ValueError('Aliased current transaction input: ' + "
                                  'relative)\n'
                                  '        values[relative] = digest(path.read_bytes())\n'
                                  '    return values\n'
                                  '\n'
                                  'def _club_check_transaction(state):\n'
                                  "    if not state['active'] or state['owner'] != "
                                  '_club_transaction_owner():\n'
                                  "        raise ValueError('Expired or foreign club reader transaction')\n"
                                  "    root = _club_exact_current_root(state['root'])\n"
                                  "    if _club_transaction_hashes(root, state['paths']) != "
                                  "state['raw_sha256']:\n"
                                  "        raise ValueError('Actual current raw input changed during club "
                                  "reader transaction')\n"
                                  '\n'
                                  'def _club_authenticate_raw(root=_CLUB_CURRENT_ROOT, *, collect=False):\n'
                                  '    root = _club_exact_current_root(root)\n'
                                  '    state = _club_active_transaction.get()\n'
                                  '    if state is None:\n'
                                  '        return _club_authenticate_full(root, collect=collect)\n'
                                  "    if state['root'] != root:\n"
                                  "        raise ValueError('Foreign root cannot use an authenticated club "
                                  "transaction')\n"
                                  '    _club_check_transaction(state)\n'
                                  "    return dict(state['predecessors']) if collect else None\n"
                                  '\n'
                                  '@_club_contextmanager\n'
                                  'def club_authenticated_transaction(root=_CLUB_CURRENT_ROOT):\n'
                                  '    root = _club_exact_current_root(root)\n'
                                  '    previous = _club_active_transaction.get()\n'
                                  '    if previous is not None:\n'
                                  "        if previous['root'] != root:\n"
                                  "            raise ValueError('Nested foreign club reader transaction')\n"
                                  '        _club_check_transaction(previous)\n'
                                  '        try:\n'
                                  '            yield\n'
                                  '        finally:\n'
                                  '            _club_check_transaction(previous)\n'
                                  '        return\n'
                                  '    predecessors = _club_authenticate_full(root, collect=True)\n'
                                  '    registration = _club_registration()\n'
                                  '    paths = tuple(sorted(set(_CLUB_E2B_SHA256) | '
                                  'set(registration.CLUB_CURRENT_INPUTS)))\n'
                                  '    raw_sha256 = _ClubMappingProxy(_club_transaction_hashes(root, '
                                  'paths))\n'
                                  '    _club_authenticate_full(root)\n'
                                  "    state = {'active': True, 'root': root, 'owner': "
                                  '_club_transaction_owner(),\n'
                                  "             'paths': paths, 'raw_sha256': raw_sha256,\n"
                                  "             'predecessors': _ClubMappingProxy(predecessors)}\n"
                                  '    token = _club_active_transaction.set(state)\n'
                                  '    try:\n'
                                  '        yield\n'
                                  '    finally:\n'
                                  '        try:\n'
                                  '            _club_check_transaction(state)\n'
                                  '            _club_authenticate_full(root)\n'
                                  '        finally:\n'
                                  "            state['active'] = False\n"
                                  '            _club_active_transaction.reset(token)\n'
                                  '\n'
                                  'def _club_tree_sha256(root):\n'
                                  '    root = Path(root)\n'
                                  '    if root.is_symlink() or root.resolve() != root:\n'
                                  "        raise ValueError('Symlinked finite club historical context')\n"
                                  '    result = {}\n'
