                                  '\n'
                                  'def _club_copy_json(value, stack=None):\n'
                                  '    kind=type(value)\n'
                                  '    if kind in (str,int,float,bool,type(None)):return value\n'
                                  "    if kind not in (list,tuple,dict):raise TypeError('Pure calculation "
                                  "accepts exact JSON builtins only')\n"
                                  '    stack=set() if stack is None else stack\n'
                                  "    if id(value) in stack:raise ValueError('Circular JSON input')\n"
                                  '    stack.add(id(value))\n'
                                  '    try:\n'
                                  '        if kind is dict:\n'
                                  '            if any(type(key) not in (str,int,float,bool,type(None)) for '
                                  "key in value):raise TypeError('Non-JSON pure mapping key')\n"
                                  '            return {key:_club_copy_json(item,stack) for key,item in '
                                  'value.items()}\n'
                                  '        result=[_club_copy_json(item,stack) for item in value]\n'
                                  '        return tuple(result) if kind is tuple else result\n'
                                  '    finally:stack.remove(id(value))\n'
                                  '\n'
                                  'def _club_make_pure(function, row, raw, *, _hash=_club_hashlib.sha256, '
                                  '_dumps=json.dumps):\n'
                                  '    tree=_club_ast.parse(raw);nodes=[n for n in tree.body if '
                                  'isinstance(n,_club_ast.FunctionDef) and n.name==function.__name__]\n'
                                  "    if len(nodes)!=1:raise ValueError('Ambiguous finite pure "
                                  "declaration')\n"
                                  '    '
                                  "node=nodes[0];lines=raw.decode().splitlines(True);source=''.join(lines[node.lineno-1:node.end_lineno]).encode()\n"
                                  "    if _hash(source).hexdigest()!=row['source_sha256']:raise "
                                  "ValueError('Changed complete pure declaration')\n"
                                  '    # Compare AST after only the declared parameter/function-name '
                                  'normalization.\n'
                                  '    if node.decorator_list or len(node.args.args)!=1 or '
                                  'node.args.posonlyargs or node.args.kwonlyargs or node.args.vararg or '
                                  'node.args.kwarg or node.args.defaults or node.returns or '
                                  "node.args.args[0].annotation:raise ValueError('Impure declaration "
                                  "signature')\n"
                                  '    parameter=node.args.args[0].arg\n'
