                                  '_hash(encoded.encode()).hexdigest()\n'
                                  "        if kind in ('json_compact','json_compact_ascii'):return encoded\n"
                                  "        raise ValueError('Unknown finite pure kind')\n"
                                  '    return pure\n'
                                  '\n'
                                  'def _club_guard_context(context):\n'
                                  '    """Isolate imports and functions in this context\'s exact physical '
                                  'namespace.\n'
                                  '\n'
                                  '    No process-global tools/Tests module, __import__, sys.path, Path, or '
                                  'filesystem\n'
                                  '    operation is rebound. Each historical module has its own import '
                                  'builtins.\n'
                                  '    """\n'
                                  "    if getattr(context, '_club_e2b_guarded', False):\n"
                                  '        context.verify()\n'
                                  '        return context\n'
                                  '    context.root = Path(context.root).absolute()\n'
                                  '    expected = dict(context.file_sha256)\n'
                                  '    if _club_tree_sha256(context.root) != expected:\n'
                                  "        raise ValueError('Finite historical reader membership is "
                                  "incomplete')\n"
                                  '    context.file_sha256 = _ClubMappingProxy(expected)\n'
                                  "    namespace = '_club_e2b_' + digest(str(context.root).encode())[:24]\n"
                                  '    modules = {}\n'
                                  '    guarded_functions = {}\n'
                                  '    guarded_managers = {}\n'
                                  "    call_frame = _ClubContextVar('club_42f_reader_' + namespace, "
                                  'default=None)\n'
                                  "    packages = {''}\n"
                                  '    for relative in expected:\n'
                                  "        if relative.endswith('.py'):\n"
                                  "            parts = relative[:-3].split('/')\n"
                                  '            for end in range(1, len(parts)):\n'
                                  "                packages.add('.'.join(parts[:end]))\n"
