                                  '                    return leave(kind, error, traceback)\n'
                                  '                def __call__(self, *args, **kwargs):\n'
                                  '                    if decorate is None:\n'
                                  "                        raise TypeError('Historical context manager is "
                                  "not a decorator')\n"
                                  '                    return decorate(*args, **kwargs)\n'
                                  '            proxy = ContextBoundary()\n'
                                  '            guarded_managers[id(value)] = (value, proxy)\n'
                                  '            guarded_managers[id(proxy)] = (proxy, proxy)\n'
                                  '            return proxy\n'
                                  '        # Returned closures, bound methods and callable objects may be '
                                  'invoked\n'
                                  '        # after their creating reader has exited. Preserve the raw '
                                  'boundary.\n'
                                  '        if callable(value) and not _club_inspect.isclass(value):\n'
                                  '            return guard_function(value)\n'
                                  '        return value\n'
                                  '\n'
                                  '    def guard_function(function):\n'
                                  '        saved = guarded_functions.get(id(function))\n'
                                  '        if saved is not None and saved[0] is function:\n'
                                  '            return saved[1]\n'
                                  '        @_club_wraps(function)\n'
                                  '        def checked(*args, **kwargs):\n'
                                  '            frame = call_frame.get()\n'
                                  '            outermost = frame is None\n'
                                  '            if outermost:\n'
                                  '                verify()\n'
                                  "                frame = {'active': True, 'owner': "
                                  '_club_transaction_owner()}\n'
                                  '                token = call_frame.set(frame)\n'
                                  "            elif not frame['active'] or frame['owner'] != "
                                  '_club_transaction_owner():\n'
                                  "                raise ValueError('Expired or foreign historical reader "
                                  "call frame')\n"
                                  '            try:\n'
                                  '                result = function(*args, **kwargs)\n'
                                  '            finally:\n'
                                  '                if outermost:\n'
                                  "                    frame['active'] = False\n"
                                  '                    call_frame.reset(token)\n'
                                  '                    verify()\n'
                                  '            return guard_result(result)\n'
                                  '        # Keep one wrapper per callable identity, including '
                                  'already-bound\n'
                                  '        # readers; do not trust caller-mutable function marker '
                                  'attributes.\n'
                                  '        guarded_functions[id(function)] = (function, checked)\n'
                                  '        guarded_functions[id(checked)] = (checked, checked)\n'
                                  '        return checked\n'
                                  '\n'
                                  '    def load_name(local):\n'
                                  '        if local in modules:\n'
                                  '            return modules[local]\n'
                                  "        relative = local.replace('.', '/') + '.py'\n"
                                  '        is_package = local in packages\n'
                                  "        init = (local.replace('.', '/') + '/' if local else '') + "
                                  "'__init__.py'\n"
                                  '        if is_package:\n'
                                  '            relative = init if init in expected else None\n'
                                  '        elif relative not in expected:\n'
                                  "            raise ModuleNotFoundError('Module outside finite e2b "
                                  "namespace: ' + local)\n"
                                  "        qualified = namespace + ('.' + local if local else '')\n"
                                  '        module = _ClubModule(qualified)\n'
                                  '        module.__package__ = qualified if is_package else '
                                  "qualified.rpartition('.')[0]\n"
                                  '        if is_package:\n'
                                  "            module.__path__ = [str(context.root / local.replace('.', "
                                  "'/'))]\n"
                                  '        modules[local] = module\n'
                                  '        _club_sys.modules[qualified] = module\n'
                                  '        if local:\n'
                                  "            parent, _, child = local.rpartition('.')\n"
                                  '            setattr(load_name(parent), child, module)\n'
                                  '        if relative is not None:\n'
                                  '            module.__file__ = str(context.root / relative)\n'
                                  '            module.__builtins__ = context.builtins\n'
                                  '            raw = (context.root / relative).read_bytes()\n'
                                  '            if digest(raw) != expected[relative]:\n'
                                  "                raise ValueError('Changed exact physical historical "
                                  "module: ' + relative)\n"
                                  "            exec(compile(raw, module.__file__, 'exec'), module.__dict__)\n"
                                  '            for attribute, value in tuple(vars(module).items()):\n'
                                  '                if _club_inspect.isfunction(value) and value.__module__ '
                                  '== qualified:\n'
                                  '                    row = _CLUB_PURE_ROWS.get((relative, attribute))\n'
                                  '                    wrapped = _club_make_pure(value, row, raw) if row is '
                                  'not None else guard_function(value)\n'
                                  '                    setattr(module, attribute, wrapped)\n'
                                  '                    if row is not None:\n'
                                  '                        guarded_functions[id(wrapped)] = (wrapped, '
                                  'wrapped)\n'
                                  '        return module\n'
                                  '\n'
                                  '    def local_name(name):\n'
                                  '        if name == namespace:\n'
                                  "            return ''\n"
                                  "        if name.startswith(namespace + '.'):\n"
                                  '            return name[len(namespace) + 1:]\n'
                                  "        if name == 'tools' or name.startswith('tools.') or name == "
                                  "'Tests' or name.startswith('Tests.'):\n"
                                  '            return name\n'
                                  "        candidate = 'tools/' + name.replace('.', '/') + '.py'\n"
                                  '        if candidate in expected:\n'
                                  "            return 'tools.' + name\n"
                                  "        candidate = 'tools.' + name\n"
                                  '        if candidate in packages:\n'
                                  '            return candidate\n'
                                  "        if name.split('.')[0] in _CLUB_LOCAL_TOOL_NAMES:\n"
                                  "            raise ModuleNotFoundError('Historical tool missing from "
                                  "finite e2b inputs: ' + name)\n"
                                  '        return None\n'
                                  '\n'
                                  '    def isolated_import(name, globals=None, locals=None, fromlist=(), '
                                  'level=0):\n'
                                  "        absolute = (_club_import_util.resolve_name('.' * level + name,\n"
                                  "                    (globals or {}).get('__package__', '')) if level else "
                                  'name)\n'
                                  '        local = local_name(absolute)\n'
                                  '        if local is None:\n'
                                  '            result = native_import(name, globals, locals, fromlist, '
                                  'level)\n'
                                  "            source = getattr(result, '__file__', None)\n"
                                  '            if source and '
