                                  'fallback.identity = identity\\n            return try await '
                                  'fallback.publicProfile(memberID: memberID)\\n        }\\n        let '
                                  'captured = identity, requestID = UUID()\\n        let bytes = try '
                                  'JSONSerialization.data(withJSONObject: [\\"id\\": memberID,\\n            '
                                  '\\"nickname\\": \\"Held profile from account \\\\(captured.accountID ?? '
                                  '0)\\"])\\n        let response = try '
                                  'JSONDecoder().decode(SocialPublicProfile.self, from: bytes)\\n        '
                                  'startedCount += 1\\n        let released = await withCheckedContinuation '
                                  '{ (continuation: CheckedContinuation<SocialPublicProfile, Never>) '
                                  'in\\n            pending[requestID] = .init(response: response, '
                                  'continuation: continuation)\\n        }\\n        // Do not check '
                                  'cancellation here: the production View must reject this\\n        // old '
                                  'response after the cancelled source task resumes successfully.\\n        '
                                  'returnedAccountID = captured.accountID; returnedMemberID = memberID; '
                                  'returnedCount += 1\\n        return released\\n    }\\n    func '
                                  'releasePendingProfiles() {\\n        let waiting = pending\\n        '
                                  'pending.removeAll()\\n        for request in waiting.values { '
                                  'request.continuation.resume(returning: request.response) }\\n    }\\n    '
                                  'func informationList() async throws -> [SocialInformation] {\\n        '
                                  'fallback.identity = identity; return try await '
                                  'fallback.informationList()\\n    }\\n    func information(id: Int) async '
